#!/usr/bin/env python3
"""Build a fully embedded offline HTML audit from analysis outputs and cached MCP artifacts."""
from pathlib import Path
import json,base64,html,hashlib
import pandas as pd
R=Path(__file__).resolve().parent
r=json.loads((R/'results.json').read_text());c=r['crude'];w=r['legacy_iptw'];d=r['diagnostics'];q=r['quality']
def fmt(v,key,scale=1):return f"{v[key]*scale:.2f} (95% CI {v[key+'_ci'][0]*scale:.2f} to {v[key+'_ci'][1]*scale:.2f})"
def fig(name,caption,alt):
    b=base64.b64encode((R/f'figures/{name}.png').read_bytes()).decode();return f'<figure><img src="data:image/png;base64,{b}" alt="{alt}"><figcaption>{caption}</figcaption></figure>'
def table(frame):return frame.to_html(index=False,border=0,escape=True,classes='data')
summary=f"Day-1 RHC was associated with higher recorded 30-day mortality: 830/2,184 (38.0%) versus 1,088/3,551 (30.6%). The crude risk difference was {fmt(c,'rd',100)} percentage points; the risk ratio was {fmt(c,'rr')}."
limits=[('Timing · critical','The dictionary defines swang1 on the first day a patient qualified for SUPPORT; the publication describes the first 24 hours of ICU care. These windows are not proven interchangeable. The snapshot has no within-day treatment or covariate timestamps. Day-1 physiology, DNR status and prognostic scores cannot all be certified as pretreatment. An exposure assigned over a day can introduce immortal-time or reverse-causation bias if follow-up starts earlier. Obtain the original timing definitions and records, then specify a grace-period strategy; do not assume a landmark analysis would estimate the same target.'),('Identification · critical','Severity and clinical indications influence both catheterization and death. Unrecorded clinician judgment, treatment decisions and hospital practice may confound the comparison. In a conceptual DAG, pretreatment severity → RHC and mortality; RHC → later physiology → mortality. Adjusting for later physiology could block mediation or open collider paths. No sufficient adjustment set has been established. Exchangeability, consistency, treatment-version definitions, positivity and no interference remain assumptions, not findings.'),('Missing data · high','cat2 is blank in 4,535/5,735 (79.1%), adld3p in 4,296 (74.9%), and urin1 in 3,028 (52.8%). A blank secondary diagnosis may mean no secondary diagnosis, but the dictionary does not confirm this. Legacy dummy encoding pools blanks with the reference category; numeric median imputation suppresses missing-value uncertainty and can distort associations. Missing indicators and omission sensitivities do not establish MAR or repair MNAR. Resolve structural blanks and timing before developing outcome-inclusive multiple imputation and clinically justified MNAR sensitivity.'),('Model and transport · high','The legacy propensity model is an additive, L2-regularized logistic model with default C=1; no nonlinearities or interactions are assessed. Good balance on included columns does not guarantee balance on joint distributions or unmeasured factors. This historical cohort came from five US teaching hospitals, 1989–1994; it does not directly represent current ICU practice. The snapshot lacks site IDs, so site clustering is not addressed.'),('Review · unresolved','This is an analyst self-audit. No human scientific approval or independent-context review has occurred. The requested later independent review remains pending. Controller reporting readiness is not asserted; this document records calculations and unresolved gates.')]
legacy=[('“All baseline covariates”','Excluding named outcomes and dates does not establish covariate timing. The reproduction uses the legacy remaining fields only to audit its arithmetic.'),('“Trim to overlap”','np.clip changes probabilities to [0.02, 0.98]. It excludes zero patients. This modifies weights and can introduce bias; it does not restore identification or define a restricted overlap population.'),('“G-computation-style OR”','The treatment coefficient from the logistic model is a conditional odds ratio, not a standardized marginal risk contrast or g-computation. Odds ratios are noncollapsible and mortality is common here.'),('“Mean balance improved”','A mean absolute SMD can hide individual failures. We save every term, show the largest initial imbalances and report maximum residual SMD. We fix the denominator at the unweighted pooled population SD; the legacy weighted-SD denominator changes the yardstick.'),('Single imputation + no intervals','The primary crude comparison requires no imputation. The exploratory weighted interval refits imputation and propensity estimation in a patient bootstrap, but still does not account for a scientifically justified missing-data model or systematic bias.'),('Network-dependent input','The original file is preserved unchanged. The estimator was transcribed to read identical supplied bytes offline; this is not an unchanged-script execution and not a reproduction of the original published matching analysis.')]
miss=pd.read_csv(R/'tables/missingness-all.csv');miss.columns=['Variable','Missing n'];miss=miss[miss['Missing n']>0];miss['% of 5,735']=(100*miss['Missing n']/r['n']).round(1)
bs=pd.read_csv(R/'tables/balance-all.csv');mb=pd.read_csv(R/'tables/missingness-balance.csv')
selected=pd.read_csv(R/'tables/table1-all.csv');selected=selected[selected.variable.isin(['age','sex','aps1','meanbp1','surv2md1'])];selected=selected.rename(columns={'variable':'Variable','group':'Exposure','denominator':'Group N','observed':'Observed n','missing':'Missing n','summary':'Summary'})
source='Connors AF Jr et al. The effectiveness of right heart catheterization in the initial care of critically ill patients. SUPPORT Investigators. JAMA. 1996;276:889–897. PMID 8782638. DOI 10.1001/jama.276.11.889.'
sections=[]
sections.append(f'''<section id="cohort"><div class="eyebrow">01 / Cohort and endpoint</div><h2>One row per patient. No analysis exclusions.</h2><p>The supplied snapshot contains 5,735 unique, nonmissing patient IDs and 62 columns. Exposure is <code>swang1 = RHC</code>; outcome is <code>dth30 = Yes</code>. Both labels are complete and binary. The primary contrast is the difference and ratio of recorded 30-day death proportions, RHC versus No RHC, in this supplied cohort. This is a retrospective analysis specification, not a preregistered analysis.</p>{fig('flow','Figure 1. The flow begins with the supplied cohort, not everyone screened for SUPPORT. Counts use original patients, not weighted pseudocounts. Earlier eligibility and screening losses cannot be reconstructed.','Participant flow: 5735 supplied and analyzed, 2184 RHC and 3551 No RHC.')}<p><strong>Outcome checks.</strong> Follow-up variable <code>t3d30</code> ranges from {q['t3d30_range'][0]:g} to {q['t3d30_range'][1]:g} days; {q['no_death_before_30_followup']} records labeled no death have follow-up below 30 days. Comparing the supplied death label with nonmissing death date minus study admission date ≤30 yields {q['death_label_date_disagreement']} disagreements. These are internal consistency checks, not independent endpoint validation. The supplied dictionary does not fully document the derived 30-day fields.</p><details><summary>Selected characteristics and full-table conventions</summary><p>Numeric fields show mean (SD), median [IQR] among observed values; categorical percentages use the whole exposure-group denominator. Physiology is described as recorded, without claiming it preceded RHC. No baseline p-values. All candidate fields are saved in tables/table1-all.csv.</p>{table(selected)}</details></section>''')
sections.append(f'''<section id="estimates"><div class="eyebrow">02 / Calculation</div><h2>The association is positive; causation is unresolved.</h2><p>{summary}</p>{fig('uncertainty',f'Figure 2. Dots are estimates and whiskers are 95% intervals. Crude intervals use independent-binomial Wald risk difference and log risk ratio. Legacy IPTW intervals use {r["bootstrap"]["successful"]} successful patient bootstrap replicates (seed 240924), refitting medians, scaling and propensity models. These quantify sampling variability under the respective analysis procedures, not bias from timing, confounding or missing-data assumptions.','Crude and exploratory weighted mortality contrasts with 95 percent uncertainty intervals.')}<div class="callout"><strong>Exploratory legacy IPTW.</strong> Weighted mortality proportions: {100*w['risk_rhc']:.1f}% with RHC and {100*w['risk_no_rhc']:.1f}% without RHC. RD {fmt(w,'rd',100)} percentage points; RR {fmt(w,'rr')}. All 5,735 patients remain. The stabilized weights are normalized separately within each group when calculating risks. These are weighted associations; the intended ATE interpretation is not identified.</div><p>The all-covariate logistic regression gave a conditional adjusted OR of {r['conditional_adjusted_or']['or']:.2f} (model-based 95% CI {r['conditional_adjusted_or']['ci'][0]:.2f}–{r['conditional_adjusted_or']['ci'][1]:.2f}; convergence: {r['conditional_adjusted_or']['converged']}). This is neither an RR nor g-computation and is not the primary result. Its model-based interval also conditions on the single-imputation design.</p></section>''')
sections.append(f'''<section id="diagnostics"><div class="eyebrow">03 / Diagnostic evidence</div><h2>Adjustment needs more than a fitted propensity score.</h2><p>Use the selector to compare diagnostic panels. All plots and controls work offline.</p><label for="panel">Diagnostic view </label><select id="panel" onchange="switchPanel(this.value)"><option value="missing">Missingness</option><option value="balance">Balance and overlap</option><option value="sensitivity">Sensitivity</option></select><div id="missing" class="panel">{fig('missingness','Figure 3. Missing proportions use 2,184 RHC and 3,551 No RHC patients as separate denominators. These are the three incomplete legacy adjustment fields. Missing death dates (2,013) and one discharge date are excluded from the propensity model; a missing death date is not automatically missing mortality.','Missingness by RHC status for secondary diagnosis, ADL, and urine output.')}{table(miss)}<p>Complete records across all legacy covariates: {q['complete_legacy_covariate_rows']:,}/{r['n']:,}. We do not use complete-case deletion. Missingness patterns are retained in tables/missingness-patterns.csv. No MCAR/MAR/MNAR mechanism has been confirmed.</p></div><div id="balance" class="panel">{fig('diagnostics','Figure 4. Left: largest 16 absolute SMDs before weighting; all encoded terms are available in tables/balance-all.csv. The dashed 0.10 threshold is a diagnostic convention, not an identification test. Right: propensity distributions before clipping, each normalized to unit area. Dotted lines mark 0.02 and 0.98; patients beyond these lines were retained.','Covariate balance before and after weighting, alongside raw propensity score overlap.')}<p>The model uses {d['features']} encoded covariates and converged in {d['iterations']} iterations. Mean |SMD| changed from {d['smd_mean_before']:.3f} to {d['smd_mean_after']:.3f}; maximum residual |SMD| is {d['smd_max_after']:.3f}, with {d['terms_above_01_after']} terms above 0.10. Raw propensity range: {d['ps_range'][0]:.4f}–{d['ps_range'][1]:.4f}; {d['clipped_n']} scores clipped. Maximum stabilized weight: {d['max_weight']:.2f}. Kish effective sample sizes: RHC {d['ess']['1']:.0f}/{r['n_rhc']:,}, No RHC {d['ess']['0']:.0f}/{r['n_no_rhc']:,}. ESS measures weight concentration, not independent information gained.</p><p>Missingness indicators were not balanced explicitly by the legacy model; their fixed-denominator SMDs are shown here.</p>{table(mb.round(3))}</div><div id="sensitivity" class="panel">{fig('sensitivity','Figure 5. Exploratory changes retain the same 5,735 patients. Clipping variants reuse the fitted propensity model. “Missing indicators” refits with explicit cat2 missing category and numeric missingness indicators; “omit sparse fields” refits without cat2, adld3p and urin1. Points have no intervals and are not independent replications or MNAR sensitivity analyses.','Point estimates of the weighted risk difference under clipping and missing-data encoding variants.')}<p>The legacy weighted RR yields a point E-value of {r['evalue_point']:.2f} using RR + √[RR(RR−1)]. This is an algebraic sensitivity benchmark for unmeasured confounding under its bounding assumptions. It does not resolve timing, exposure versions, missingness, measurement error, selection, or model misspecification. No E-value confidence limit is presented and no causal robustness threshold is claimed.</p></div></section>''')
sections.append('<section id="critique"><div class="eyebrow">04 / Legacy audit</div><h2>What the script calculates—and what its labels overstate.</h2>'+table(pd.DataFrame(legacy,columns=['Legacy claim / choice','Audit finding']))+'</section>')
sections.append('<section id="limits"><div class="eyebrow">05 / Interpretation gates</div><h2>Why this is not a completed causal analysis.</h2>'+''.join(f'<article class="limitation"><h3>{a}</h3><p>{b}</p></article>' for a,b in limits)+'<p><strong>Proposed next work:</strong> establish the exact study-day origin and within-day measurement order; adjudicate structural blanks and sentinel values; define the treatment strategy and causal DAG; obtain a clinically justified adjustment set and missing-data plan; then reassess balance, positivity, uncertainty, and independent review. No bootstrap or model change can substitute for these steps.</p></section>')
# The tool figure is preserved and embedded as a separate exploratory source check.
b=base64.b64encode((R/'mcp_artifacts/17dc396ce3f345b7a07bcecc96a38f78/figure.png').read_bytes()).decode()
sections.append(f'''<section id="provenance"><div class="eyebrow">06 / Reproduction and provenance</div><h2>Local inputs. Inspectable decisions. Unresolved gates.</h2><p><strong>Sources.</strong> {source} The actual PubMed abstract retrieved by the MCP tool supports the study setting and historical design. It reports a matched OR of 1.24 (95% CI 1.03–1.49), which is a different analysis and estimand scale from this weighted RR. It is background context, not numerical validation of the legacy estimator. The public data and dictionary were supplied locally from hbiostat.org; they were not downloaded again.</p><p><strong>Input SHA-256:</strong> <code class="hash">{r['input_sha256']}</code>. Source retrieval occurred 2026-09-24 UTC. Cached responses, URLs, retrieval times and file checksums are preserved under mcp_artifacts/. Only the original-study abstract was used substantively; the two other search hits do not establish this analysis's validity.</p><table><thead><tr><th>Added component</th><th>What it actually did</th></tr></thead><tbody><tr><td>Original specialist skills</td><td>Provided policy for estimand, time ordering, missingness, diagnostic choices, critique and qualified reporting. No skill confers approval.</td></tr><tr><td>Controller</td><td>Executed route, advance and settle. Causal route completed target definition, then blocked at preparation for timing. Inferential route completed target, data and calculation, then blocked at evaluation for pending independent review. Both terminated at a configured one-block no-progress stop; neither reports success. See workflow-transitions.json.</td></tr><tr><td>MemoryStore</td><td>Persisted four scoped analyst-checked decisions/facts, source references and a composite input/contract fingerprint in project-memory.sqlite3. Retrieved them for the analysis stage before fitting. Retrieved scope/timing constrained labels; profile constrained missingness diagnostics; source distinguished published matching from legacy weighting. Attribution explicitly says analyst, not human approval. See memory-retrieval.txt.</td></tr><tr><td>Native MCP</td><td>Imported identical rhc.csv; profiled all columns; listed chart examples; rendered the age histogram below from that profile; retrieved PubMed citations and abstracts. Profile results informed sparse-field handling; the dictionary and abstract informed timing and source caveats. Tool artifacts remain exploratory and unreviewed.</td></tr><tr><td>Local Python</td><td>Computed crude and legacy estimates, 120 pipeline bootstrap replicates, diagnostics, sensitivities and Matplotlib figures. No external model API, no package installation, no Jev, no delegation.</td></tr></tbody></table><details><summary>Native MCP age-distribution check</summary><figure><img class="mcp" src="data:image/png;base64,{b}" alt="MCP histogram of age in all 5735 patients"><figcaption>Figure 6. Native MCP rendering, all 5,735 ages; zero rows omitted. This source-check figure uses the server's default style; analytical figures use the report palette. It supports inspection of the supplied cohort's age distribution, not causal readiness. Dataset artifact 3160fbf4c1c04a6b9240f701bb6582a7; profile c74883de0afd431daa369af1a4814b22; chart 17dc396ce3f345b7a07bcecc96a38f78. Original PNG/SVG, chart specification and provenance are retained.</figcaption></figure></details><p><strong>Reproduce offline:</strong></p><pre>/tmp/biostat-rhc-analysis-env/bin/python analysis.py
/tmp/biostat-rhc-analysis-env/bin/python build_report.py</pre><p>Run from this folder. The analysis imports the read-only runtime at /Users/amiee/Projects_code/biostat-superpowers. Package versions are recorded in requirements-observed.txt; the environment is reused, not installed. Figures are embedded in this HTML, so this file alone can be read offline. Tables, code, database and raw cached sources remain separate audit artifacts. Source hashes and generated figure hashes are listed in artifact-manifest.json. No remote fonts, libraries or CDNs.</p><p><strong>Scope of omissions.</strong> No multiple imputation, MNAR analysis, timestamp reconstruction, site-cluster uncertainty, negative control, subgroup search, or new clinical validation was completed. No multiplicity adjustment was made; sensitivity estimates are exploratory. Extreme/sentinel values are retained to reproduce the legacy estimator (including {q['zero_weight_values']} zero body-weight values). The audit is structured around STROBE reporting domains; full checklist compliance is not claimed.</p></section>''')
css='''*{box-sizing:border-box}body{margin:0;background:#f2f5f5;color:#183344;font:17px/1.65 system-ui,-apple-system,Segoe UI,sans-serif}header{background:#123747;color:white;padding:64px max(6vw,24px) 48px}header .eyebrow{color:#a8d7e3}h1{font-size:clamp(36px,5vw,64px);line-height:1.08;letter-spacing:-2px;max-width:950px;margin:18px 0 24px}header p{max-width:850px;color:#e1edf0;font-size:21px}.badge{display:inline-block;padding:6px 13px;background:#f5d8b8;color:#4d3019;border-radius:4px;font-size:14px;font-weight:750}.eyebrow{text-transform:uppercase;letter-spacing:2px;font-size:12px;font-weight:800;color:#176b86}nav{display:flex;gap:25px;flex-wrap:wrap;padding:18px max(6vw,24px);background:white;border-bottom:1px solid #d5e0e4}a{color:#176b86}main{max-width:1180px;margin:35px auto;padding:0 24px}section{background:white;padding:38px 42px;margin:24px 0;border:1px solid #dce5e7;border-radius:10px}h2{font-size:30px;line-height:1.25;letter-spacing:-.6px}h3{font-size:20px}figure{margin:26px 0}img{width:100%;height:auto;display:block}figcaption{font-size:14px;color:#536b79;line-height:1.6;border-left:3px solid #9bbecb;padding:8px 15px}table{border-collapse:collapse;width:100%;font-size:14px;display:block;overflow-x:auto}td,th{text-align:left;padding:12px 14px;border-bottom:1px solid #dde6e9;vertical-align:top}th{background:#e8f0f2}td:first-child{font-weight:600}.callout{background:#e9f2f4;border-left:4px solid #176b86;padding:22px}.limitation{border-top:1px solid #e2e8eb;padding:5px 0}.hash{overflow-wrap:anywhere;font-size:13px}code,pre{font-size:14px}pre{background:#eff3f5;padding:20px;overflow:auto}select{font:inherit;padding:8px 16px;margin:10px 0 20px;color:#183344;background:white;border:1px solid #6b8b98;border-radius:5px}details{margin:20px 0;padding:15px;background:#f4f7f8}summary{cursor:pointer;font-weight:650}.mcp{max-width:820px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;max-width:1020px;margin-top:30px}.metric{border-top:1px solid #527784;padding-top:15px}.metric b{display:block;font-size:34px;line-height:1.2}.metric span{font-size:14px;color:#c5dce4}footer{padding:30px;text-align:center;color:#536b79;font-size:14px}@media(max-width:700px){section{padding:24px 18px}main{padding:0 10px}.metrics{grid-template-columns:1fr}h1{letter-spacing:-1px}}@media print{nav,select,label{display:none}.panel{display:block!important}section{break-inside:avoid}body{background:white}details{display:block}}'''
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RHC · an association under audit</title><style>{css}</style></head><body><header><div class="eyebrow">SUPPORT / RHC · observational study audit · 24 September 2026</div><h1>Higher mortality with day-1 RHC.<br>What can we conclude?</h1><p>Recorded mortality is higher among patients who received RHC. Adjustment reproduces a positive association, but timing, missing data and confounding prevent a completed causal interpretation.</p><span class="badge">ASSOCIATIONAL FINDING · CAUSAL GATES UNRESOLVED</span><div class="metrics"><div class="metric"><b>5,735</b><span>patients · zero analysis exclusions</span></div><div class="metric"><b>+{100*c['rd']:.1f} pp</b><span>crude mortality risk difference</span></div><div class="metric"><b>{c['rr']:.2f}×</b><span>crude 30-day mortality risk ratio</span></div></div></header><nav aria-label="Report sections"><a href="#cohort">Cohort</a><a href="#estimates">Estimates</a><a href="#diagnostics">Diagnostics</a><a href="#critique">Legacy audit</a><a href="#limits">Limits</a><a href="#provenance">Reproduce</a></nav><main>{''.join(sections)}</main><footer>Local analysis audit · no human scientific approval · independent review pending</footer><script>function switchPanel(id){{document.querySelectorAll('.panel').forEach(p=>p.style.display=p.id===id?'block':'none')}}switchPanel('missing');</script></body></html>'''
(R/'report.html').write_text(page)
md=f'''# Day-1 RHC and 30-day mortality

{summary}

**Interpretation:** higher recorded mortality among RHC recipients, not proof that RHC caused harm.

- **Population:** all 5,735 supplied patients; 2,184 RHC, 3,551 No RHC; no exclusions, no missing treatment/outcome labels, unique IDs. Original screening denominator unavailable.
- **Exploratory legacy IPTW:** weighted risks {100*w['risk_rhc']:.1f}% versus {100*w['risk_no_rhc']:.1f}%; RD {fmt(w,'rd',100)} percentage points; RR {fmt(w,'rr')}. 120 full-pipeline patient bootstrap replicates, seed 240924. Intervals reflect sampling under the single-imputation procedure, not uncertainty from bias or a valid MI model.
- **Balance/overlap:** {d['features']} encoded terms; mean absolute SMD {d['smd_mean_before']:.3f} → {d['smd_mean_after']:.3f}; max after {d['smd_max_after']:.3f}; {d['terms_above_01_after']} terms above 0.10. {d['clipped_n']} propensity scores clipped; no patients trimmed. Effective N: RHC {d['ess']['1']:.0f}, No RHC {d['ess']['0']:.0f}.

## Why causal interpretation is unresolved

1. **Timing:** study day 1 means first qualifying SUPPORT day; ICU first-24-hour wording is not proven equivalent. No within-day treatment/covariate ordering. Physiology, DNR and prognosis cannot all be certified pretreatment; immortal-time, reverse-causation and post-treatment adjustment risks remain.
2. **Missingness:** cat2 4,535/5,735; adld3p 4,296/5,735; urin1 3,028/5,735. Structural blanks are unconfirmed. Legacy categorical coding folds blanks into reference; median fill is not multiple imputation. Encoding/omission sensitivity does not validate MAR or MNAR.
3. **Identification:** no justified sufficient adjustment set; confounding by indication and unmeasured clinical judgment remain. Positivity, consistency, no interference and model adequacy are not established. Historical five-hospital data do not establish current clinical effects.
4. **Review:** analyst self-audit only; independent review pending and no human scientific approval. Site clustering cannot be addressed from these fields.

## Legacy corrections

The preserved script was not executed unchanged: its estimator was transcribed to use the supplied bytes offline. Clipping is not overlap trimming. Its logistic treatment coefficient is a conditional OR, not g-computation (OR {r['conditional_adjusted_or']['or']:.2f}). Balance now uses a fixed unweighted SD and all-term diagnostics. Point E-value {r['evalue_point']:.2f} is an assumption-dependent confounding benchmark, not causal validation. Alternative clipping and missingness specifications are exploratory point estimates, not MNAR analyses. No new clinical value corrections were made.

## Added components and artifacts

- **Controller:** actual route/advance/settle transitions in workflow-transitions.json. Causal branch blocked at preparation; inferential branch blocked at independent evaluation. Both stop at the configured one-block no-progress threshold; neither is marked successful.
- **MemoryStore:** project-memory.sqlite3 stores four analyst-attributed, fingerprint-bound records. Retrieved scope/timing constrained labeling, profile informed missingness handling, and source distinguished published matching from legacy IPTW. Retrieval saved in memory-retrieval.txt; no human approval inferred.
- **Native MCP:** imported/profiled the identical CSV, rendered a profiled age histogram, retrieved PubMed abstract and citations. Raw responses, chart specification, figures, hashes, timestamps and provenance remain in mcp_artifacts/. Tool outputs are exploratory, not approved evidence.
- **Local Python:** analysis.py computes estimates, diagnostics, 120 bootstrap replicates and figures; build_report.py produces a self-contained offline report.html. No package installation, external model APIs, Jev, or delegation.

View **report.html** for figures, interactive diagnostic panels, captions and fuller limitations. See **results.json**, **tables/**, **figures/**, **analysis-contract.json**, **decision-log.md**, and **artifact-manifest.json** for audit details. All images are embedded; no CDN dependency.

Reproduce offline:

```sh
/tmp/biostat-rhc-analysis-env/bin/python analysis.py
/tmp/biostat-rhc-analysis-env/bin/python build_report.py
```

Requires the supplied environment and read-only runtime at /Users/amiee/Projects_code/biostat-superpowers. Input SHA-256: `{r['input_sha256']}`. Software versions: requirements-observed.txt.

Source: {source} MCP-retrieved abstract confirms setting/design; the published matching OR is not this IPTW estimator. Dictionary and CSV were supplied from https://hbiostat.org/data/repo/rhc.html and https://hbiostat.org/data/repo/rhc.csv. Source retrieval cached 2026-09-24.
'''
(R/'report.md').write_text(md)
(R/'decision-log.md').write_text('''# Decision log · analyst-authored

- Defined primary target before fitting: supplied-label crude 30-day RD/RR in all supplied patients. No claim of preregistration.
- Confirmed input SHA against SOURCE.md; retained original legacy file and identical patient data.
- Read original specialist policies; no delegation per study instructions. Independent scientific review remains pending.
- Used dictionary and retrieved PMID 8782638 abstract to distinguish qualifying study day from first 24 hours of ICU care and published matching from legacy weighting.
- MCP profile showed three highly incomplete candidate fields. Retained legacy encoding only for exploratory reproduction; no silent complete-case deletion. Missing-data mechanism unconfirmed; MI/MNAR work deferred pending timing and structural-blank adjudication.
- MemoryStore recorded four analyst-reviewed scoped records with composite input/contract fingerprint, then retrieved them before analysis. Retrieval constrained model labeling, missingness diagnostics and source comparison; it did not authorize readiness.
- Executed actual controller transitions. Causal branch blocked on preparation; inferential branch blocked on independent evaluation. Stop policy is one blocked result, appropriate to this bounded audit. No reporting/causal completion or human confirmation was fabricated.
- Reproduced C=1 standardized logistic propensity, median fill, 0.02 clipping and stabilized normalized risks. Added 120 patient bootstrap refits. No interval claimed to cover confounding, timing, imputation-model uncertainty or hospital clustering.
- Used fixed unweighted pooled SD for before/after SMD; preserved all terms. Added clipping and missingness encoding/omission sensitivities without selecting a preferred causal model.
- Follow-up needs: exact treatment/measurement timestamps and time-zero definition; structural cat2 blanks; clinical sentinel/range review; defensible DAG/adjustment set; congenial MI and MNAR sensitivity; site-aware uncertainty; independent artifact review.
''')
